<script setup lang="ts">
import { ArrowRight, Download, ImageDown, Smartphone } from '@lucide/vue'
import { ref } from 'vue'
import AppDialog from './AppDialog.vue'
import wechatQr from '@/assets/wechat-qr.png'
import { saveWechatQrCode } from '@/infrastructure/files/wechat-qr-service'

defineProps<{ open: boolean; reason: string }>()
const emit = defineEmits<{ close: [] }>()

const saveState = ref<'idle' | 'done' | 'error'>('idle')

async function saveQrCode(): Promise<void> {
  saveState.value = 'idle'
  try {
    await saveWechatQrCode(wechatQr)
    saveState.value = 'done'
    setTimeout(() => { saveState.value = 'idle' }, 2500)
  } catch {
    saveState.value = 'error'
  }
}
</script>

<template>
  <AppDialog :open="open" position="center" title="授权码暂时无法使用" @close="emit('close')">
    <div class="license-invalid">
      <div class="reason">
        <p>{{ reason }}</p>
      </div>
      <section class="wechat-help" aria-labelledby="wechat-guide-title">
        <h3 id="wechat-guide-title">添加作者微信</h3>
        <div class="qr-stage">
          <img :src="wechatQr" alt="作者微信二维码" class="qr" />
        </div>
        <div class="guide-flow" aria-label="添加作者微信步骤">
          <div class="guide-step">
            <span class="guide-icon" aria-hidden="true"><ImageDown :size="25" /></span>
            <span>保存图片<br />到相册</span>
          </div>
          <ArrowRight class="guide-arrow" :size="24" aria-hidden="true" />
          <div class="guide-step">
            <span class="guide-icon" aria-hidden="true"><Smartphone :size="25" /></span>
            <span>打开微信<br />扫一扫</span>
          </div>
        </div>
      </section>
    </div>
    <template #actions>
      <button class="button secondary" type="button" @click="saveQrCode">
        <Download :size="18" />{{ saveState === 'done' ? '已保存' : saveState === 'error' ? '保存失败，重试' : '保存二维码' }}
      </button>
    </template>
  </AppDialog>
</template>

