<script setup lang="ts">
import { onBeforeUnmount, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import AppDialog from '@/components/AppDialog.vue'
import NetworkConfirmDialog from '@/components/NetworkConfirmDialog.vue'
import LicenseInvalidDialog from '@/components/LicenseInvalidDialog.vue'
import UpdateProgressDialog, { type UpdatePhase } from '@/components/UpdateProgressDialog.vue'
import { applyUpdate } from '@/infrastructure/updater/offline-runtime'
import { decideUpdate, fetchReleaseManifest } from '@/infrastructure/updater/release-manifest'
import { ensureDeviceId } from '@/infrastructure/licensing/device-id'
import { humanizeReason, requestVerify } from '@/infrastructure/licensing/license-api'
import { useAppStore } from '@/stores/app-store'
import { rememberUpdateReturnRoute } from '@/app/update-return-route'

/**
 * 更新流程组件（无常驻 UI，只渲染弹窗）：设置页「版本号」行点击 start() 触发。
 * 流程：联网确认弹窗 → 进度弹窗 5 步 → 完成后联网查台账同步授权 → 失效/成功弹窗。
 * 更新结果标记（reload 前写入）在本组件 onMounted 读出统一弹窗（原 V1.0.34 逻辑迁移自 UpdatePage）。
 * 保留测试构建的模拟更新钩子（VITE_UPDATE_SIMULATION）。
 */
const store = useAppStore()
const route = useRoute()
const appVersion = import.meta.env.VITE_APP_VERSION ?? '1.0.5'
const nativeBuild = Number.parseInt(import.meta.env.VITE_NATIVE_BUILD ?? '4', 10)
const simulationEnabled = import.meta.env.VITE_UPDATE_SIMULATION === 'true'
const UPDATE_JUST_INSTALLED_KEY = 'money-app-update-just-installed'
const simulationLicense = import.meta.env.VITE_UPDATE_SIMULATION_LICENSE === 'invalid' ? 'invalid' : 'valid'
const simulatedVersion = '1.0.24'

const networkConfirmOpen = ref(false)
const progressOpen = ref(false)
const progressPhase = ref<UpdatePhase>('connecting')
const progressPercent = ref<number | null>(null)
const progressVersion = ref('')
const invalidOpen = ref(false)
const invalidReason = ref('')
const updateSuccessOpen = ref(false)
const updateSuccessVersion = ref('')
const busy = ref(false)
let abortController: AbortController | null = null
let resolveProgressAcknowledgement: (() => void) | null = null
let resolveInvalidAcknowledgement: (() => void) | null = null

const PHASE_MIN_INTERVAL_MS = 1_000
let lastPhaseShownAt = 0
let phaseChain: Promise<void> = Promise.resolve()
function enqueuePhase(phase: UpdatePhase): void {
  phaseChain = phaseChain.then(async () => {
    const wait = PHASE_MIN_INTERVAL_MS - (Date.now() - lastPhaseShownAt)
    if (wait > 0) await new Promise((resolve) => setTimeout(resolve, wait))
    if (progressOpen.value) progressPhase.value = phase
    lastPhaseShownAt = Date.now()
  })
}

/** 入口：弹出联网确认（设置页「版本号」行点击） */
function start(): void {
  if (!busy.value) networkConfirmOpen.value = true
}

function cancelUpdate(): void {
  abortController?.abort()
  progressOpen.value = false
  busy.value = false
}

function handleProgressClose(): void {
  if (progressPhase.value === 'success' || progressPhase.value === 'current') {
    progressOpen.value = false
    resolveProgressAcknowledgement?.()
    resolveProgressAcknowledgement = null
    return
  }
  cancelUpdate()
}

function waitForProgressAcknowledgement(): Promise<void> {
  return new Promise((resolve) => { resolveProgressAcknowledgement = resolve })
}

function waitForInvalidAcknowledgement(): Promise<void> {
  return new Promise((resolve) => { resolveInvalidAcknowledgement = resolve })
}

function waitForSimulation(ms: number): Promise<boolean> {
  const signal = abortController?.signal
  return new Promise((resolve) => {
    if (signal?.aborted) {
      resolve(false)
      return
    }
    const timer = window.setTimeout(() => {
      signal?.removeEventListener('abort', onAbort)
      resolve(true)
    }, ms)
    const onAbort = () => {
      window.clearTimeout(timer)
      signal?.removeEventListener('abort', onAbort)
      resolve(false)
    }
    signal?.addEventListener('abort', onAbort, { once: true })
  })
}

async function runSimulatedUpdate(): Promise<boolean> {
  progressPhase.value = 'connecting'
  if (!await waitForSimulation(600)) return false

  progressPhase.value = 'checking'
  if (!await waitForSimulation(900)) return false

  progressPhase.value = 'discovered'
  progressVersion.value = simulatedVersion
  if (!await waitForSimulation(600)) return false

  progressPhase.value = 'downloading'
  progressPercent.value = 0
  for (let percent = 0; percent <= 100; percent += 5) {
    progressPercent.value = percent
    if (!await waitForSimulation(100)) return false
  }

  progressPhase.value = 'success'
  await waitForProgressAcknowledgement()
  if (abortController?.signal.aborted) return false

  if (!await waitForSimulation(800)) return false
  if (simulationLicense === 'invalid') {
    invalidReason.value = '授权码已停用，请联系作者。'
    invalidOpen.value = true
    await waitForInvalidAcknowledgement()
    if (abortController?.signal.aborted) return false
    return true
  }
  return true
}

async function runCheckAndInstall(): Promise<void> {
  networkConfirmOpen.value = false
  busy.value = true
  abortController = new AbortController()
  progressOpen.value = true
  progressPhase.value = 'connecting'
  lastPhaseShownAt = Date.now()
  phaseChain = Promise.resolve()
  progressPercent.value = null
  progressVersion.value = ''

  try {
    if (simulationEnabled) {
      const completed = await runSimulatedUpdate()
      if (!completed) {
        progressOpen.value = false
        busy.value = false
        return
      }
      progressOpen.value = false
      busy.value = false
      return
    }

    enqueuePhase('checking')
    const manifest = await fetchReleaseManifest(import.meta.env.VITE_UPDATE_BASE_URL ?? '')
    const decision = decideUpdate(manifest, appVersion, nativeBuild)
    if (decision.kind === 'current') {
      enqueuePhase('current')
      await waitForProgressAcknowledgement()
      progressOpen.value = false
      busy.value = false
      return
    }
    enqueuePhase('discovered')
    progressVersion.value = manifest.productVersion
    const result = await applyUpdate(decision, {
      signal: abortController.signal,
      onPhase: enqueuePhase,
      onProgress: (percent) => { progressPercent.value = percent },
      beforeCommit: syncLicenseBeforeCommit,
    })
    if (result.status === 'failed') throw result.error
    if (result.status === 'cancelled') {
      progressOpen.value = false
      busy.value = false
      return
    }
    progressOpen.value = false
    busy.value = false
  } catch {
    progressOpen.value = false
    busy.value = false
    store.notify('更新失败，当前版本和本地数据不受影响，可稍后再试', 'error')
  } finally {
    abortController = null
  }
}

async function syncLicenseBeforeCommit(): Promise<void> {
  await waitForProgressAcknowledgement()
  if (abortController?.signal.aborted) return
  // 更新完成会触发原生 WebView reload；先记住设置页，启动时恢复到同一路由。
  rememberUpdateReturnRoute(route.fullPath)
  const rememberResult = (license: 'valid' | 'invalid', reason = ''): void => {
    if (progressVersion.value) {
      localStorage.setItem(UPDATE_JUST_INSTALLED_KEY, JSON.stringify({ version: progressVersion.value, license, reason }))
    }
  }
  const settings = await store.repository.getSettings()
  if (!settings.licenseCode) {
    rememberResult('valid')
    return
  }
  let deviceId: string
  try {
    deviceId = await ensureDeviceId(store.repository)
  } catch {
    rememberResult('valid')
    return
  }
  try {
    const result = await requestVerify({ code: settings.licenseCode, deviceId })
    if (!result.ok) {
      const reasonText = humanizeReason(result.reason)
      // 更新复查只改变当前会话的授权状态，绝不删除用户保存的授权码。
      // 本地授权码只能由授权页的主动解绑流程清除。
      store.markLicenseInvalid(reasonText)
      rememberResult('invalid', reasonText)
      return
    }
    await store.refreshLicense()
    rememberResult('valid')
  } catch {
    rememberResult('valid')
  }
}

function closeInvalid(): void {
  invalidOpen.value = false
  invalidReason.value = ''
  resolveInvalidAcknowledgement?.()
  resolveInvalidAcknowledgement = null
}

function closeUpdateSuccess(): void {
  updateSuccessOpen.value = false
  updateSuccessVersion.value = ''
}

function resetInvalidState(): void {
  invalidOpen.value = false
  invalidReason.value = ''
  updateSuccessOpen.value = false
  updateSuccessVersion.value = ''
}

function onVisibilityChange(): void {
  if (!document.hidden && !busy.value) resetInvalidState()
}

onMounted(() => {
  resetInvalidState()
  document.addEventListener('visibilitychange', onVisibilityChange)
  // 更新结果弹窗（V1.0.34 逻辑）：reload 前写入的标记在此统一弹出
  const justInstalled = localStorage.getItem(UPDATE_JUST_INSTALLED_KEY)
  if (justInstalled) {
    localStorage.removeItem(UPDATE_JUST_INSTALLED_KEY)
    try {
      const result = JSON.parse(justInstalled) as { version: string; license: 'valid' | 'invalid'; reason?: string }
      if (result.license === 'invalid') {
        invalidReason.value = `已成功更新到 ${result.version}。${result.reason ?? '授权码不可用，请联系作者。'}`
        invalidOpen.value = true
      } else {
        updateSuccessVersion.value = result.version
        updateSuccessOpen.value = true
      }
    } catch {
      updateSuccessVersion.value = justInstalled
      updateSuccessOpen.value = true
    }
  }
})

onBeforeUnmount(() => {
  abortController?.abort()
  resolveProgressAcknowledgement?.()
  resolveInvalidAcknowledgement?.()
  resolveProgressAcknowledgement = null
  resolveInvalidAcknowledgement = null
  document.removeEventListener('visibilitychange', onVisibilityChange)
})

defineExpose({ start })
</script>

<template>
  <NetworkConfirmDialog :open="networkConfirmOpen" @close="networkConfirmOpen = false" @confirm="runCheckAndInstall()" />

  <UpdateProgressDialog
    :open="progressOpen"
    :phase="progressPhase"
    :progress="progressPercent"
    :version="progressVersion"
    @close="handleProgressClose"
  />

  <AppDialog :open="updateSuccessOpen" position="center" title="版本更新成功" @close="closeUpdateSuccess">
    <p>已成功更新到 {{ updateSuccessVersion }}，可正常使用。</p>
    <template #actions>
      <button class="button primary" type="button" @click="closeUpdateSuccess">好的</button>
    </template>
  </AppDialog>

  <LicenseInvalidDialog :open="invalidOpen" :reason="invalidReason" @close="closeInvalid" />
</template>
