<script setup lang="ts">
import { onMounted, ref, toRef, watch } from 'vue'
import { useOverlayBackClose } from '@/ui/overlay-back-stack'

/**
 * 底部上滑选择器（参考系统分享面板风格）：圆角顶 + 抓手 + 标题 + 选项列表 + 取消。
 * options：icon 组件 + 文字 + 描述；点击选项 emit select(id) 并自动关闭。
 */
export interface ActionSheetOption {
  id: string
  label: string
  description?: string
  icon?: unknown
}

const props = defineProps<{
  open: boolean
  title: string
  options: ActionSheetOption[]
}>()
const emit = defineEmits<{ close: []; select: [id: string] }>()
const dialog = ref<HTMLDialogElement>()
// 安卓返回手势优先关闭选择器（而不是后退页面）
useOverlayBackClose(toRef(props, 'open'), () => emit('close'))

watch(() => props.open, (open) => {
  const element = dialog.value
  if (!element) return
  if (open && !element.open) element.showModal()
  else if (!open && element.open) element.close()
}, { immediate: true })

onMounted(() => {
  dialog.value?.addEventListener('cancel', (event) => {
    event.preventDefault()
    emit('close')
  })
})

function onSelect(id: string): void {
  emit('select', id)
  emit('close')
}
</script>

<template>
  <dialog ref="dialog" class="action-sheet" @click="emit('close')">
    <section class="sheet-panel" @click.stop>
      <span class="drag-handle" aria-hidden="true" />
      <h2 class="sheet-title">{{ title }}</h2>
      <button
        v-for="option in options"
        :key="option.id"
        type="button"
        class="sheet-option"
        @click="onSelect(option.id)"
      >
        <span v-if="option.icon" class="option-icon"><component :is="option.icon" :size="21" /></span>
        <span class="option-main">
          <strong>{{ option.label }}</strong>
          <small v-if="option.description">{{ option.description }}</small>
        </span>
      </button>
      <button type="button" class="sheet-cancel" @click="emit('close')">取消</button>
    </section>
  </dialog>
</template>

<style scoped>
.action-sheet { inset: 0; width: 100%; max-width: 560px; height: 100%; max-height: none; margin: 0; padding: 0; border: 0; background: transparent; }
.action-sheet:not([open]) { display: none; }
.action-sheet::backdrop { background: rgb(10 18 32 / 48%); backdrop-filter: blur(2px); }
.sheet-panel { position: absolute; right: 0; bottom: 0; left: 0; display: grid; gap: 2px; padding: 6px 12px calc(12px + var(--safe-bottom)); border-radius: 24px 24px 0 0; background: var(--color-surface); box-shadow: 0 -12px 40px rgb(10 18 32 / 18%); }
.drag-handle { width: 36px; height: 4px; margin: 6px auto 10px; border-radius: 999px; background: var(--color-border); }
.sheet-title { margin: 0 0 10px; padding: 0 8px; font-size: 16px; }
/* 选项 = 全宽圆角块（参考截图）：浅灰底整块可点，icon + 标题 + 描述 */
.sheet-option { display: grid; width: 100%; min-height: 66px; grid-template-columns: 42px minmax(0, 1fr); align-items: center; gap: 12px; margin-bottom: 10px; padding: 10px 14px; border: 0; border-radius: 16px; background: var(--color-surface-muted); color: var(--color-text); text-align: left; cursor: pointer; }
.sheet-option:active { background: var(--color-border); }
.option-icon { display: grid; width: 42px; height: 42px; place-items: center; border-radius: 50%; background: var(--color-surface); color: var(--color-primary); box-shadow: 0 1px 4px rgb(10 18 32 / 8%); }
.option-main { display: flex; min-width: 0; flex-direction: column; gap: 2px; }
.option-main strong { font-size: 16px; }
.option-main small { color: var(--color-text-secondary); font-size: 13px; }
/* 取消与选项同款整块 */
.sheet-cancel { width: 100%; min-height: 54px; margin-top: 2px; border: 0; border-radius: 16px; background: var(--color-surface-muted); color: var(--color-text-secondary); font-size: 16px; font-weight: 600; cursor: pointer; }
@media (min-width: 640px) {
  .action-sheet { inset: 0; width: min(560px, calc(100% - 32px)); height: fit-content; margin: auto; }
  .sheet-panel { position: static; border-radius: var(--radius-lg); }
}
</style>
