<script setup lang="ts">
import { computed, ref } from 'vue'
import {
  ArchiveRestore, BellRing, ChevronRight, Download, Eraser, FolderTree, Info, KeyRound, RefreshCw, Save, Share2, TriangleAlert,
} from '@lucide/vue'
import { useAppStore } from '@/stores/app-store'
import UpdateFlow from '@/features/settings/UpdateFlow.vue'
import ActionSheet from '@/components/ActionSheet.vue'
import AppDialog from '@/components/AppDialog.vue'
import ConfirmGraphic from '@/components/ConfirmGraphic.vue'
import { useBackupActions } from '@/features/settings/use-backup-actions'

const store = useAppStore()
const appVersion = import.meta.env.VITE_APP_VERSION ?? '1.0.4'
const updateFlow = ref<InstanceType<typeof UpdateFlow>>()
const backup = useBackupActions()
const backupSheetOpen = ref(false)
const licenseLabel = computed(() => ({
  active: '已激活', expired: '授权已过期', invalid: '授权异常', unactivated: '未激活',
}[store.license.kind]))

const backupSheetOptions = [
  { id: 'local', label: '备份到手机', description: '保存到「下载」文件夹（Download/money_backup.csv）', icon: Download },
  { id: 'share', label: '备份并分享', description: '分享到微信 / 网盘等位置保存', icon: Share2 },
]

function onBackupSelect(id: string): void {
  if (id === 'local') void backup.backupToLocal()
  if (id === 'share') void backup.backupAndShare()
}

/** 上次备份时间的友好文案：今天 / 昨天 / n天前 / n个月前 / M月D日 / Y年M月D日；从未备份显示「未备份」 */
function formatRelativeBackupDate(at: string | undefined): string {
  if (!at) return '未备份'
  const date = new Date(at)
  if (Number.isNaN(date.getTime())) return '未备份'
  const now = new Date()
  const startOf = (d: Date) => new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime()
  const dayDiff = Math.round((startOf(now) - startOf(date)) / 86_400_000)
  if (dayDiff <= 0) return '今天'
  if (dayDiff === 1) return '昨天'
  if (dayDiff < 30) return `${dayDiff}天前`
  const monthDiff = (now.getFullYear() - date.getFullYear()) * 12 + (now.getMonth() - date.getMonth())
  if (monthDiff < 12) return `${Math.max(monthDiff, 1)}个月前`
  if (now.getFullYear() === date.getFullYear()) return `${date.getMonth() + 1}月${date.getDate()}日`
  return `${date.getFullYear()}年${date.getMonth() + 1}月${date.getDate()}日`
}

/** 数据备份行的右侧值：[相对时间]已备份 */
const backupRelative = computed(() => {
  const relative = formatRelativeBackupDate(store.settings.lastBackupAt)
  return relative === '未备份' ? relative : `${relative}已备份`
})

const reminderLabel = computed(() => store.settings.backupReminderEnabled === false ? '未开启' : '已开启')

/** 跳二级页的行（授权码在前，分类管理在后） */
const linkRows = computed(() => [
  { title: '授权码', icon: KeyRound, value: licenseLabel.value, route: '/settings/license' },
  { title: '分类管理', icon: FolderTree, value: '', route: '/settings/categories' },
])
</script>

<template>
  <main class="page settings-page">
    <section class="settings-list card">
      <RouterLink v-for="row in linkRows" :key="row.title" :to="row.route" class="settings-row">
        <component :is="row.icon" :size="20" aria-hidden="true" />
        <span class="row-title">{{ row.title }}</span>
        <span class="row-value" :class="{ placeholder: !row.value }">{{ row.value }}</span>
        <ChevronRight :size="18" class="row-chevron" aria-hidden="true" />
      </RouterLink>
    </section>

    <section class="settings-list card">
      <!-- 数据备份：上滑选择备份方式 -->
      <button type="button" class="settings-row" @click="backupSheetOpen = true">
        <Save :size="20" aria-hidden="true" />
        <span class="row-title">数据备份</span>
        <span class="row-value">{{ backupRelative }}</span>
        <ChevronRight :size="18" class="row-chevron" aria-hidden="true" />
      </button>
      <!-- 备份恢复：直接调起文件选择 -->
      <button type="button" class="settings-row" :disabled="backup.busy.value" @click="backup.chooseRestore">
        <ArchiveRestore :size="20" aria-hidden="true" />
        <span class="row-title">备份恢复</span>
        <span class="row-value placeholder"> </span>
        <ChevronRight :size="18" class="row-chevron" aria-hidden="true" />
      </button>
      <!-- 备份提醒：跳二级表单页 -->
      <RouterLink to="/settings/backup-reminder" class="settings-row">
        <BellRing :size="20" aria-hidden="true" />
        <span class="row-title">备份提醒</span>
        <span class="row-value">{{ reminderLabel }}</span>
        <ChevronRight :size="18" class="row-chevron" aria-hidden="true" />
      </RouterLink>
      <!-- 数据格式化：图文确认弹窗 -->
      <button type="button" class="settings-row" :disabled="backup.busy.value" @click="backup.confirmFormatOpen.value = true">
        <Eraser :size="20" aria-hidden="true" />
        <span class="row-title">数据格式化</span>
        <span class="row-value placeholder"> </span>
        <ChevronRight :size="18" class="row-chevron" aria-hidden="true" />
      </button>
    </section>

    <section class="settings-list card">
      <!-- 版本号：点击原地弹联网确认并检查更新，不进二级页 -->
      <button type="button" class="settings-row" @click="updateFlow?.start()">
        <RefreshCw :size="20" aria-hidden="true" />
        <span class="row-title">版本号</span>
        <span class="row-value">v{{ appVersion }}</span>
        <ChevronRight :size="18" class="row-chevron" aria-hidden="true" />
      </button>
      <RouterLink to="/settings/about" class="settings-row">
        <Info :size="20" aria-hidden="true" />
        <span class="row-title">关于我们</span>
        <span class="row-value placeholder"> </span>
        <ChevronRight :size="18" class="row-chevron" aria-hidden="true" />
      </RouterLink>
    </section>

    <!-- 备份方式上滑选择器 -->
    <ActionSheet :open="backupSheetOpen" title="选择备份方式" :options="backupSheetOptions" @close="backupSheetOpen = false" @select="onBackupSelect" />

    <!-- 备份恢复确认（图文居中式，按钮等宽） -->
    <AppDialog :open="Boolean(backup.pendingRestore.value)" title="确认恢复备份" position="center" @close="backup.pendingRestore.value = undefined">
      <ConfirmGraphic :icon="ArchiveRestore" strong="将替换当前账本数据" :sub="`恢复「${backup.pendingRestore.value?.name ?? ''}」；旧版流水 CSV 会与现有流水合并，请确认文件来源可靠`" />
      <template #actions>
        <button class="button secondary equal-action" type="button" @click="backup.pendingRestore.value = undefined">取消</button>
        <button class="button primary equal-action" type="button" :disabled="backup.busy.value" @click="backup.executeRestore">确认恢复</button>
      </template>
    </AppDialog>

    <!-- 数据格式化：图文确认弹窗（按钮等宽，无分割线） -->
    <AppDialog :open="backup.confirmFormatOpen.value" title="格式化全部数据" position="center" @close="backup.confirmFormatOpen.value = false">
      <div class="format-confirm">
        <span class="format-icon"><TriangleAlert :size="30" aria-hidden="true" /></span>
        <p class="format-strong">删除后不可恢复</p>
      </div>
      <template #actions>
        <button class="button secondary equal-action" type="button" @click="backup.confirmFormatOpen.value = false">取消</button>
        <button class="button danger equal-action" type="button" :disabled="backup.busy.value" @click="backup.executeFormat">{{ backup.busy.value ? '执行中…' : '确认格式化' }}</button>
      </template>
    </AppDialog>

    <UpdateFlow ref="updateFlow" />
  </main>
</template>

