import { ref } from 'vue'
import { Capacitor } from '@capacitor/core'
import { useAppStore } from '@/stores/app-store'
import { exportCsv, restoreBackup, restoreCsvBackup } from '@/domain/services/backup'
import { pickTextFile, saveBackupFile, shareTextFile } from '@/infrastructure/files/backup-file-service'

/**
 * 备份三动作（设置页直连入口共用，逻辑迁自 BackupPage）：
 * - backupToLocal / backupAndShare：生成 CSV 备份到手机「下载」或分享
 * - chooseRestore：直接调起文件选择 → 确认弹窗（pendingRestore）→ executeConfirmed
 * - formatAll：图形化确认弹窗（confirmFormat）→ 先自动安全备份再清空
 * 确认弹窗的文案与渲染由调用方（设置页模板）负责，本 composable 只管状态与执行。
 */
export function useBackupActions() {
  const store = useAppStore()
  const busy = ref(false)
  /** 待确认的恢复文件（选完文件即弹确认） */
  const pendingRestore = ref<{ name: string; text: string }>()
  /** 待确认的格式化（图文确认弹窗用） */
  const confirmFormatOpen = ref(false)

  async function backupToLocal(): Promise<void> {
    if (!Capacitor.isNativePlatform()) {
      store.notify('网页版不支持保存到手机文件夹，请点「备份并分享」，选择“存储到文件”即可保存', 'info')
      return
    }
    if (busy.value) return
    busy.value = true
    try {
      const snapshot = await store.repository.exportSnapshot()
      await saveBackupFile(exportCsv(snapshot), 'csv')
      await store.updateSettings({ lastBackupAt: new Date().toISOString() })
      store.notify('已备份到手机「下载」文件夹（Download/money_backup.csv）', 'success')
    } catch (cause) {
      store.notify(cause instanceof Error ? cause.message : '备份失败', 'error')
    } finally {
      busy.value = false
    }
  }

  async function backupAndShare(): Promise<void> {
    if (busy.value) return
    busy.value = true
    try {
      const snapshot = await store.repository.exportSnapshot()
      const text = exportCsv(snapshot)
      if (Capacitor.isNativePlatform()) await saveBackupFile(text, 'csv')
      await store.updateSettings({ lastBackupAt: new Date().toISOString() })
      try {
        await shareTextFile('money_backup.csv', text, 'text/csv;charset=utf-8')
      } catch (cause) {
        store.notify(cause instanceof Error ? cause.message : '分享已取消', 'error')
      }
      store.notify(Capacitor.isNativePlatform() ? '备份完成，文件已留底在手机「下载」文件夹' : '备份完成，请将文件保存到安全位置', 'success')
    } catch (cause) {
      store.notify(cause instanceof Error ? cause.message : '备份失败', 'error')
    } finally {
      busy.value = false
    }
  }

  /** 备份恢复：直接调起系统文件选择；选中后由设置页弹确认（pendingRestore） */
  async function chooseRestore(): Promise<void> {
    if (busy.value) return
    const file = await pickTextFile()
    if (!file) return
    pendingRestore.value = file
  }

  async function executeRestore(): Promise<void> {
    const file = pendingRestore.value
    if (!file) return
    busy.value = true
    try {
      if (file.name.toLowerCase().endsWith('.csv')) {
        const result = await restoreCsvBackup(store.repository, file.text)
        store.notify(result.kind === 'full' ? `已完整恢复 ${result.count} 条流水` : `已导入 ${result.count} 条旧版流水`, 'success')
      } else {
        const count = await restoreBackup(store.repository, file.text)
        store.notify(`已恢复 ${count} 条流水`, 'success')
      }
      await store.refresh()
      pendingRestore.value = undefined
    } catch (cause) {
      store.notify(cause instanceof Error ? cause.message : '恢复失败，原数据未改变', 'error')
    } finally {
      busy.value = false
    }
  }

  /** 数据格式化：确认后直接清空全部数据（用户拍板 2026-09-17：不再自动生成安全备份） */
  async function executeFormat(): Promise<void> {
    if (busy.value) return
    busy.value = true
    try {
      await store.repository.resetAll()
      await store.refresh()
      confirmFormatOpen.value = false
      store.notify('已完成格式化', 'success')
    } catch (cause) {
      store.notify(cause instanceof Error ? cause.message : '操作失败，原数据未改变', 'error')
    } finally {
      busy.value = false
    }
  }

  return {
    busy,
    pendingRestore,
    confirmFormatOpen,
    backupToLocal,
    backupAndShare,
    chooseRestore,
    executeRestore,
    executeFormat,
  }
}
